            <tr>
              <th scope="row" colspan="4">Amount due</th>
              <td data-testid="invoice-amount-due">{{ amount(inv.amountDue) }}</td>
            </tr>
            <tr>
              <th scope="row" colspan="4">Written off (worth under $1.00 left)</th>
